# Tokyo Night storm 调色板：https://github.com/folke/tokyonight.nvim
# shellcheck shell=bash disable=SC2034  # 主题变量由 common.sh 和 theme.sh 使用。
THEME_NAME="Tokyo Night Storm"
THEME_NVIM_COLORSCHEME="tokyonight-storm"

COLOR_BG=0xff24283b          # storm bg：栏和弹窗底色
COLOR_SURFACE=0xff1f2335     # bg_dark：胶囊和模块底色
COLOR_SURFACE_ALT=0xff292e42 # bg_highlight：悬停、选中行和进度轨道
COLOR_BORDER=0xff565f89      # comment：边框
COLOR_TEXT=0xffc0caf5        # fg：主要文字
COLOR_SUBTEXT=0xffa9b1d6     # fg_dark：次要文字
COLOR_MUTED=0xff565f89       # comment：弱化和未激活内容
COLOR_ACCENT=0xff7aa2f7      # blue：当前 space 和强调
COLOR_ON_ACCENT=0xff24283b   # bg：强调色上的文字
COLOR_SUCCESS=0xff9ece6a     # green：成功状态
COLOR_WARNING=0xffff9e64     # orange：警告状态
COLOR_DANGER=0xfff7768e      # red：危险状态
